import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.C-si7TFR.js";const p=JSON.parse('{"title":"Create and configure agents","description":"","frontmatter":{"title":"Create and configure agents"},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md"}'),i={name:"guide/agents.md"};function r(s,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="create-and-configure-agents" tabindex="-1">Create and configure agents <a class="header-anchor" href="#create-and-configure-agents" aria-label="Permalink to &quot;Create and configure agents&quot;">​</a></h1><h2 id="create-a-standalone-agent" tabindex="-1">Create a standalone agent <a class="header-anchor" href="#create-a-standalone-agent" aria-label="Permalink to &quot;Create a standalone agent&quot;">​</a></h2><ol><li>Select <strong>Create Agent</strong> in the agent list.</li><li>Enter a name, description and system instructions covering scope, output format and prohibited actions.</li><li>Set a working directory only when needed. Do not point tools at unrelated system or sensitive-data directories.</li><li>Select only the required built-in tools, MCP tools, knowledge bases and workflows.</li><li>Save and test with a small task that has no side effects.</li></ol><h2 id="capability-prerequisites" tabindex="-1">Capability prerequisites <a class="header-anchor" href="#capability-prerequisites" aria-label="Permalink to &quot;Capability prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Purpose</th><th>Prerequisite</th></tr></thead><tbody><tr><td>Built-in tools</td><td>Provided file, search and other capabilities</td><td>Check tool permissions, directory scope and service requirements</td></tr><tr><td>Skills</td><td>Task methods and operating conventions</td><td>Prepare shared or agent-specific skills</td></tr><tr><td>MCP tools</td><td>Connect external tool services</td><td>The tool is enabled with a valid protocol and endpoint</td></tr><tr><td>Knowledge</td><td>Retrieve reference material</td><td>A text or vector knowledge base and model dependencies are ready</td></tr><tr><td>Workflow tools</td><td>Invoke deterministic processes as tools</td><td>The workflow is enabled and uses a sync or async API trigger</td></tr></tbody></table><p>Only enabled workflows with supported API triggers appear as workflow tools. A normal manual workflow cannot simply be selected as one. <a href="./../sub_workflow.html">Sub-workflows</a> are a separate orchestration mechanism.</p><h2 id="built-in-agents" tabindex="-1">Built-in agents <a class="header-anchor" href="#built-in-agents" aria-label="Permalink to &quot;Built-in agents&quot;">​</a></h2><p>Use the parent agent card&#39;s action menu to add a built-in agent. It belongs to the parent card and is managed in its built-in section. Its ownership, import/export and deletion behavior differ from standalone agents. Use the provided upgrade action to change ownership instead of copying configuration manually.</p><p>See <a href="./sub-agents.html">Compose sub-agents</a>.</p><h2 id="import-and-export" tabindex="-1">Import and export <a class="header-anchor" href="#import-and-export" aria-label="Permalink to &quot;Import and export&quot;">​</a></h2><p>Inspect instructions, tools, working directories and external endpoints before importing an external configuration. Configuration is not inherently trusted. Never include API keys, secrets or personal information in public configuration files.</p><h2 id="verification-and-troubleshooting" tabindex="-1">Verification and troubleshooting <a class="header-anchor" href="#verification-and-troubleshooting" aria-label="Permalink to &quot;Verification and troubleshooting&quot;">​</a></h2><ul><li><strong>A tool is missing:</strong> check that it exists and is enabled in the current project and role.</li><li><strong>The model is unavailable:</strong> follow the model setup guidance in the conversation. Tool selection does not replace model configuration.</li><li><strong>An unexpected action occurred:</strong> disable the related channel or schedule, narrow instructions and tool selection, and inspect execution records.</li></ul>',13)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
